package io.github.saigyo.aslan.spec.data

import io.github.saigyo.aslan.spec.JsonataFunction
import io.github.saigyo.aslan.spec.JsonataParameter

private fun fn(name: String, category: String, page: String, parameters: List<JsonataParameter>, description: String, supported: Boolean = true,
        url: String = "https://docs.jsonata.org/$page-functions#${name.lowercase()}") =
    JsonataFunction(name, parameters, category, description, url, supported = supported)

/** The JSONata 2.0.6 built-in functions, followed by the five that Step Functions adds. Descriptions are adapted from the JSONata documentation. */
internal val jsonataFunctionList = listOf(
    fn("string", "String", "string", listOf(JsonataParameter("arg", optional = true), JsonataParameter("prettify", optional = true)),
        "Turns a value into a string. Strings stay as they are, functions become an empty string, and other values are written as JSON; with prettify set to true the JSON is indented."),
    fn("length", "String", "string", listOf(JsonataParameter("str", optional = true)),
        "Returns the number of characters in a string. Without an argument it uses the context value."),
    fn("substring", "String", "string", listOf(JsonataParameter("str"), JsonataParameter("start"), JsonataParameter("length", optional = true)),
        "Returns the part of a string that begins at the zero-based position start, up to length characters when given."),
    fn("substringBefore", "String", "string", listOf(JsonataParameter("str"), JsonataParameter("chars")),
        "Returns the part of a string before the first occurrence of chars, or the whole string if chars does not occur."),
    fn("substringAfter", "String", "string", listOf(JsonataParameter("str"), JsonataParameter("chars")),
        "Returns the part of a string after the first occurrence of chars, or the whole string if chars does not occur."),
    fn("uppercase", "String", "string", listOf(JsonataParameter("str", optional = true)),
        "Returns the string with all characters converted to uppercase."),
    fn("lowercase", "String", "string", listOf(JsonataParameter("str", optional = true)),
        "Returns the string with all characters converted to lowercase."),
    fn("trim", "String", "string", listOf(JsonataParameter("str", optional = true)),
        "Replaces tabs and line breaks with spaces, collapses runs of spaces to one, and removes leading and trailing spaces."),
    fn("pad", "String", "string", listOf(JsonataParameter("str"), JsonataParameter("width"), JsonataParameter("char", optional = true)),
        "Pads a string to at least the absolute value of width characters, on the right for a positive width and on the left for a negative one. The padding character defaults to a space."),
    fn("contains", "String", "string", listOf(JsonataParameter("str"), JsonataParameter("pattern")),
        "Returns true if the string contains the text, or matches the regular expression, given as pattern."),
    fn("split", "String", "string", listOf(JsonataParameter("str"), JsonataParameter("separator"), JsonataParameter("limit", optional = true)),
        "Splits a string into an array of substrings around a separator, which can be text or a regular expression. The optional limit caps the number of substrings."),
    fn("join", "String", "string", listOf(JsonataParameter("array"), JsonataParameter("separator", optional = true)),
        "Joins an array of strings into one string, with the optional separator between the items."),
    fn("match", "String", "string", listOf(JsonataParameter("str"), JsonataParameter("pattern"), JsonataParameter("limit", optional = true)),
        "Applies a regular expression to a string and returns an array of objects describing each match, up to limit matches."),
    fn("replace", "String", "string", listOf(JsonataParameter("str"), JsonataParameter("pattern"), JsonataParameter("replacement"), JsonataParameter("limit", optional = true)),
        "Replaces occurrences of pattern (text or regular expression) in a string with replacement, at most limit times when given."),
    fn("eval", "String", "string", listOf(JsonataParameter("expr"), JsonataParameter("context", optional = true)),
        "Evaluates a string holding JSON or a JSONata expression. Step Functions does not support it; use \$parse for JSON text.", supported = false),
    fn("base64encode", "String", "string", listOf(JsonataParameter("str", optional = true)),
        "Converts a string to its base 64 representation. Every character must be in the range 0x00 to 0xFF."),
    fn("base64decode", "String", "string", listOf(JsonataParameter("str", optional = true)),
        "Converts a base 64 encoded string back to a string, using UTF-8."),
    fn("encodeUrlComponent", "String", "string", listOf(JsonataParameter("str", optional = true)),
        "Encodes a URL component by replacing certain characters with escape sequences of their UTF-8 bytes."),
    fn("encodeUrl", "String", "string", listOf(JsonataParameter("str", optional = true)),
        "Encodes a whole URL by replacing certain characters with escape sequences of their UTF-8 bytes."),
    fn("decodeUrlComponent", "String", "string", listOf(JsonataParameter("str", optional = true)),
