    fn("decodeUrl", "String", "string", listOf(JsonataParameter("str", optional = true)),
        "Decodes a URL that was encoded by \$encodeUrl."),
    fn("number", "Numeric", "numeric", listOf(JsonataParameter("arg", optional = true)),
