    fn("floor", "Numeric", "numeric", listOf(JsonataParameter("number", optional = true)),
        "Rounds a number down to the nearest integer that is not larger than it."),
    fn("ceil", "Numeric", "numeric", listOf(JsonataParameter("number", optional = true)),
        "Rounds a number up to the nearest integer that is not smaller than it."),
    fn("round", "Numeric", "numeric", listOf(JsonataParameter("number"), JsonataParameter("precision", optional = true)),
