    fn("formatBase", "Numeric", "numeric", listOf(JsonataParameter("number"), JsonataParameter("radix", optional = true)),
        "Formats a number as an integer in the given base from 2 to 36; the base defaults to 10."),
    fn("formatInteger", "Numeric", "numeric", listOf(JsonataParameter("number"), JsonataParameter("picture")),
        "Formats a number as an integer following a picture string, for example as words or Roman numerals."),
    fn("parseInteger", "Numeric", "numeric", listOf(JsonataParameter("string"), JsonataParameter("picture")),
        "Parses text written in the format of a \$formatInteger picture string back into an integer."),
    fn("sum", "Aggregation", "aggregation", listOf(JsonataParameter("array")),
        "Returns the sum of an array of numbers."),
    fn("max", "Aggregation", "aggregation", listOf(JsonataParameter("array")),
        "Returns the largest number in an array of numbers."),
    fn("min", "Aggregation", "aggregation", listOf(JsonataParameter("array")),
        "Returns the smallest number in an array of numbers."),
    fn("average", "Aggregation", "aggregation", listOf(JsonataParameter("array")),
        "Returns the mean of an array of numbers."),
    fn("boolean", "Boolean", "boolean", listOf(JsonataParameter("arg", optional = true)),
        "Converts a value to a boolean: empty strings, zero, null, empty arrays and objects, and functions give false, and most other values give true."),
    fn("not", "Boolean", "boolean", listOf(JsonataParameter("arg", optional = true)),
        "Returns the logical negation of the argument after converting it to a boolean."),
    fn("exists", "Boolean", "boolean", listOf(JsonataParameter("arg")),
        "Returns true if the expression yields a value, and false if it matches nothing, for example a path to a missing field."),
