        "Returns the number of items in an array. A value that is not an array counts as one item."),
    fn("append", "Array", "array", listOf(JsonataParameter("array1"), JsonataParameter("array2")),
        "Returns the items of the first array followed by those of the second; a value that is not an array is treated as an array of one item."),
    fn("sort", "Array", "array", listOf(JsonataParameter("array"), JsonataParameter("function", optional = true)),
        "Returns the array in sorted order. Without a comparator function the items must be all numbers or all strings; a comparator takes two items and returns true if the first should come after the second."),
    fn("reverse", "Array", "array", listOf(JsonataParameter("array")),
        "Returns the items of an array in reverse order."),
    fn("shuffle", "Array", "array", listOf(JsonataParameter("array")),
        "Returns the items of an array in random order."),
    fn("distinct", "Array", "array", listOf(JsonataParameter("array")),
        "Returns the array without duplicate values; values are compared by deep equality."),
    fn("zip", "Array", "array", listOf(JsonataParameter("array1"), JsonataParameter("array2...")),
        "Combines the arrays position by position into an array of arrays. The result is as long as the shortest input."),
    fn("keys", "Object", "object", listOf(JsonataParameter("object", optional = true)),
        "Returns an array of the keys of an object. For an array of objects, it returns the distinct keys of all of them."),
    fn("lookup", "Object", "object", listOf(JsonataParameter("object"), JsonataParameter("key")),
        "Returns the value stored under a key in an object. For an array of objects, it returns the values from all of them."),
    fn("spread", "Object", "object", listOf(JsonataParameter("object", optional = true)),
        "Splits an object into an array of objects, each holding one key and value of the original."),
    fn("merge", "Object", "object", listOf(JsonataParameter("array")),
        "Merges an array of objects into one object. When keys repeat, the value from the last object wins."),
    fn("each", "Object", "object", listOf(JsonataParameter("object"), JsonataParameter("function")),
        "Calls a function with the value and key of each pair in an object and returns the results as an array."),
    fn("error", "Object", "object", listOf(JsonataParameter("message", optional = true)),
        "Stops the evaluation with an error carrying the optional message."),
    fn("assert", "Object", "object", listOf(JsonataParameter("condition"), JsonataParameter("message", optional = true)),
        "Returns nothing if the condition is true and stops with an error carrying the message if it is false."),
    fn("type", "Object", "object", listOf(JsonataParameter("value")),
        "Returns the type of a value as one of the strings null, number, string, boolean, array, object or function."),
    fn("clone", "Object", "object", listOf(JsonataParameter("arg", optional = true)),
        "Returns a deep copy of a value. JSONata 2.0.6 has this function, but the published documentation does not describe it.",
