    fn("now", "Date/Time", "date-time", listOf(JsonataParameter("picture", optional = true), JsonataParameter("timezone", optional = true)),
        "Returns the current time as a UTC timestamp string in ISO 8601 format; every call within one evaluation gives the same value. A picture and timezone format it as \$fromMillis does."),
    fn("millis", "Date/Time", "date-time", listOf(),
        "Returns the current time as milliseconds since the Unix epoch; every call within one evaluation gives the same value."),
    fn("fromMillis", "Date/Time", "date-time", listOf(JsonataParameter("number"), JsonataParameter("picture", optional = true), JsonataParameter("timezone", optional = true)),
