    fn("map", "Higher order", "higher-order", listOf(JsonataParameter("array"), JsonataParameter("function")),
        "Returns an array with the result of calling a function on each item of an array."),
    fn("filter", "Higher order", "higher-order", listOf(JsonataParameter("array"), JsonataParameter("function")),
        "Returns the items of an array for which the predicate function returns true."),
    fn("single", "Higher order", "higher-order", listOf(JsonataParameter("array"), JsonataParameter("function", optional = true)),
        "Returns the only item for which the predicate function returns true, and fails if there is not exactly one."),
    fn("reduce", "Higher order", "higher-order", listOf(JsonataParameter("array"), JsonataParameter("function"), JsonataParameter("init", optional = true)),
        "Combines the items of an array into one value by applying a function of two arguments successively, starting from the optional init."),
    fn("sift", "Higher order", "higher-order", listOf(JsonataParameter("object"), JsonataParameter("function", optional = true)),
        "Returns an object with only the pairs of the input object for which the predicate function returns true."),
    JsonataFunction("partition", listOf(JsonataParameter("array"), JsonataParameter("size")), "Step Functions", "Splits an array into chunks of the given size and returns an array of arrays. The last chunk is shorter if the items do not divide evenly. It replaces the intrinsic function States.ArrayPartition.", Doc.JSONATA, stepFunctionsOnly = true),
    JsonataFunction("range", listOf(JsonataParameter("start"), JsonataParameter("end"), JsonataParameter("step")), "Step Functions", "Returns an array of integers from start up to end, moving by step, which can be negative. It replaces the intrinsic function States.ArrayRange.", Doc.JSONATA, stepFunctionsOnly = true),
    JsonataFunction("hash", listOf(JsonataParameter("source"), JsonataParameter("algorithm")), "Step Functions", "Returns the hash of a string as text. The algorithm is one of MD5, SHA-1, SHA-256, SHA-384 and SHA-512. It replaces the intrinsic function States.Hash.", Doc.JSONATA, stepFunctionsOnly = true),
    JsonataFunction("uuid", listOf(), "Step Functions", "Returns a new random version 4 UUID as text. It replaces the intrinsic function States.UUID.", Doc.JSONATA, stepFunctionsOnly = true),
    JsonataFunction("parse", listOf(JsonataParameter("json")), "Step Functions", "Turns a string holding JSON into a value. Use it instead of \$eval, which Step Functions does not support.", Doc.JSONATA, stepFunctionsOnly = true),
